pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        address ownerBefore = c.owner();
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // only the current owner may change ownership; then it takes effect
            assertTrue(actor == ownerBefore && c.owner() == newOwner);
        } catch {
            // non-owner callers must be rejected and ownership must stay unchanged
            assertTrue(actor != ownerBefore && c.owner() == ownerBefore);
        }
    }
}

