contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));
        vm.assume(attacker != c.owner());

        vm.prank(attacker);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // Universal rule: a non-owner can never change ownership; a call from
        // a non-owner must fail and leave the owner unchanged.
        assertTrue((!ok) || (c.owner() == newOwner && ok == false), "non-owner changed ownership");
    }
}
